insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('i-bin-total-hii-liig-in-gaunzn-toog-im-bett-und-kumm-nimma-hoch', 'I bin total hii - liig in gaunzn Toog im Bett und kumm nimma hoch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich bin total hin - lieg den ganzen Tag im Bett und komm nimmer hoch!', '[{"kategorie": "wörtlich", "text": "\"Ich bin total kaputt - lieg den ganzen Tag im Bett und komm nicht mehr hoch!\"  2. Ich bin körperlich total am Ende – ich liege den ganzen Tag flach und schaffe es nicht mal aufzustehen!  3. Ich bin fix und fertig – lieg im Bett wie ein nasser Sack und beweg mich keinen Meter mehr!"}]'::jsonb, ''),
  ('dea-is-ned-nua-deppad-dea-is-richtig-hii-im-schaedl', 'Dea is ned nua deppad, dea is richtig hii im Schädl!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Der ist nicht nur deppert, der ist richtig hin im Schädel!', '[{"kategorie": "wörtlich", "text": "\"Der ist nicht nur bescheuert, der ist richtig kaputt im Kopf!\"  2. Der hat nicht nur ’ne Schraube locker – der ist kaputt bis in die Fußnägel!  3. Der ist nicht nur leicht daneben, der ist komplett durch!"}]'::jsonb, ''),
  ('dea-is-hii-im-schaedl', 'Dea is hii im Schädl!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Der ist hin im Schädel!', '[{"kategorie": "wörtlich", "text": "\"Der ist kaputt im Kopf\""}, {"kategorie": "", "text": "Der hat einen Sprung in der Schüssel!  3. Der hat sie nicht mehr alle!  4. [[Dea]] is hiinnich in da Marüün!"}]'::jsonb, ''),
  ('dea-is-hiinnich-in-da-marueuen', 'Dea is hiinnich in da Marüün!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Der ist hinnig in der Marille!', '[{"kategorie": "wörtlich", "text": "\"Der ist kaputt im Kopf\""}, {"kategorie": "", "text": "Der hat einen [[Sprung]] in der Schüssel!   3. Der hat sie nicht mehr alle!  4. [[Dea]] is hii im Schädl!"}]'::jsonb, ''),
  ('dea-hod-an-schbrung-in-da-schissl', 'Dea hod an Schbrung in da Schissl!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Der hat einen Sprung in der Schüssel!', '[{"kategorie": "wörtlich", "text": "\"Der ist kaputt im Kopf\""}, {"kategorie": "", "text": "Der hat sie nicht mehr alle!  3. [[Dea]] is hiinnich in da Marüün!  4. [[Dea]] is hii im Schädl!"}]'::jsonb, ''),
  ('dea-hod-an-wuam-in-da-marueuen', 'Dea hod an Wuam in da Marüün!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Der hat ''nen Wurm in der Marille!', '[{"kategorie": "wörtlich", "text": "\"Der hat ''nen Sprung in der Schüssel!\"  2. Der ist kaputt im Kopf\""}, {"kategorie": "", "text": "Der hat sie nicht mehr alle!  4. [[Dea]] is hiinnich in da Marüün!  5. [[Dea]] is hii im Schädl!"}]'::jsonb, ''),
  ('hiinnich-auf-d-schleich-sei', 'hiinnich auf d''Schleich sei', '', '', '', 'Wiener Sprüche, die sitzen!', 'hinnig auf den Schläuchen sein', '[{"kategorie": "wörtlich", "text": "\"kaputt auf den Schläuchen sein\""}, {"kategorie": "scherzhaft für", "text": "\"fußkrank sein\", \"schlecht zu Fuß sein\", \"nicht mehr richtig gehen können\" (aufgrund einer Gehbehinderung, Fuß- oder Beinverletzung)"}]'::jsonb, ''),
  ('da-opa-is-zwoa-zaach-owa-mittlawaeu-isa-echt-hiinnich-auf-de-schleich', 'Da Opa is zwoa zaach, owa mittlawäu isa echt hiinnich auf de Schleich!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Der Opa ist zwar zäh, aber mittlerweile ist er echt hinnig auf den Schläuchen!', '[{"kategorie": "wörtlich", "text": "\"Der Opa ist zwar zäh, aber mittlerweile tragen ihn seine Beine nicht mehr wirklich!\"  2. Der Opa ist zwar zäh, aber mittlerweile streiken seine Beine beim Gehen!  3. Unser Opa ist zäh wie eh und je, aber seine Beine machen nicht mehr so richtig mit!"}]'::jsonb, 'hiinnich auf d''Schleich sei'),
  ('wem-iwad-schleich-haun', 'wem iwad Schleich haun', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'jemandem über die Schläche hauen', '[{"kategorie": "wörtlich, Fußballerjargon", "text": "\"jemandem gegen die Beine treten\""}, {"kategorie": "", "text": "jemandem gegen die Schienbeine treten"}, {"kategorie": "", "text": "[[wem iwad Rearln haun]], [[wem de Sawän ohaun]]"}]'::jsonb, 'Da Sechsa hod eam glei in da drittn Minuutn uandlich iwad Schleich ghaud - do woa de Marschrichtung kloa!'),
  ('da-sechsa-hod-eam-glei-in-da-drittn-minuutn-uandlich-iwad-schleich-ghaud-do-woa-de-marschrichtung-kloa', 'Da Sechsa hod eam glei in da drittn Minuutn uandlich iwad Schleich ghaud - do woa de Marschrichtung kloa!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der Sechser hat ihm gleich in der dritten Minute ordentlich über die Schläuche gehauen – da war die Marschrichtung klar!', '[{"kategorie": "wörtlich", "text": "\"Der Sechser hat ihm gleich in der dritten Minute ordentlich gegen die Schienbeine getreten – da war die Marschrichtung klar!\"  2. Der Sechser hat direkt mal ein Zeichen gesetzt – volle Kanne auf die Knochen, und das schon in der dritten Minute!  3. Der defensive Mittelfeldspieler ist eingestiegen wie ein Holzfäller – hat seinen Gegenspieler schon in der dritten Minute  abgeräumt, bevor der zweimal atmen konnte!"}]'::jsonb, ''),
  ('gestan-woara-no-feian-und-heit-schbueueda-in-hiinnichn-klassische-montoogstaktik', 'Gestan woara no feian und heit schbüüda in Hiinnichn - klassische Montoogstaktik!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Gestern war er noch feiern und heute spielt er den Hinnigen – klassische Montagstaktik!', '[{"kategorie": "wörtlich", "text": "\"Gestern war er noch feiern, heute spielt er den Sterbenskranken – klassische Montagstaktik!\"  2. Gestern noch die Tanzfläche gerockt, mimt er heute den Totkranken - Montagsklassiker!  3. Gestern noch feiern bis zum Umfallen, und heute dann den Pflegefall markieren - typisch Montag!"}]'::jsonb, ''),
  ('heast-du-hiinnicha-schleich-di', 'Heast, du Hiinnicha, schleich di!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Hör zu, du Hinniger, schleich dich!', '[{"kategorie": "wörtlich", "text": "\"Hey, du Vollidiot, mach ''nen Abgang!\"  2. Zisch ab, du Hirnschüssler!  3. Hey, du Trottel, verputz dich - aber schnell!"}]'::jsonb, ''),
  ('waunns-in-aana-tua-himlitzn-tuad-ziagd-a-weeda-auf', 'Waunns in aana Tua himlitzn tuad, ziagd a Weeda auf!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn es in einer Tour himmelitzt, zieht ein Wetter auf!', '[{"kategorie": "wörtlich", "text": "\"Wenn am Himmel ununterbrochen Wetterleuchten zu sehen sind, zieht ein schweres Gewitter auf!\"  2. Dauerhafte Wetterleuchten am Himmel deuten auf ein herannahendes starkes Gewitter hin!  3. Zeigt sich am Himmel durchgehend Wetterleuchten, kündigt sich ein schweres Unwetter an!"}]'::jsonb, ''),
  ('wia-kau-ma-soo-a-hianeedal-sei-und-trotzdem-an-fueueraschein-haum', 'Wia kau ma soo a Hianeedal sei und trotzdem an Füüraschein haum?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wie kann man so ein Hirnederl sein und trotzdem einen Führerschein haben?', '[{"kategorie": "wörtlich", "text": "\"Wie kann es sein, dass ein solcher Depp einen Führerschein besitzt?\"  2. Wie dieser Volltrottel zu einem Führerschein gekommen ist, wird wohl ewig ein Rätsel bleiben!  3. Bei diesem Schwachkopf fragt man sich, ob er den Führerschein im Überraschungsei gefunden hat!"}]'::jsonb, ''),
  ('da-holla-bliad-im-mai-und-daunn-kumman-de-gaunzn-bio-heinis-und-mochn-an-sirup-draus', 'Da Holla bliad im Mai - und daunn kumman de gaunzn Bio-Heinis und mochn an Sirup draus!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Der Holler blüht im Mai – und dann kommen die ganzen Bio-Heinis und machen Sirup draus!', '[{"kategorie": "wörtlich", "text": "\"Im Mai blüht der Holunder – und dann kommen die ganzen Bio-Heinis und machen Sirup draus!\"  2. Im Mai geht der Holunder auf – und sofort pilgern die ganzen Öko-Touristen mit ihren Einmachgläsern an!  3. Holunderblüte im Mai? Schon kommen die Bio-Jünger aus allen Löchern und rühren Sirup wie im Mittelalter!"}]'::jsonb, ''),
  ('schwoaza-holla', 'schwoaza Holla', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'schwarzer Holler', '[{"kategorie": "wörtlich", "text": "\"schwarzer Holler\" (vom mittelhochdeutschen \"swarzer holer\"=\"schwarzer Holler\")"}, {"kategorie": "bot.", "text": "\"schwarzer Holunder\" (Pflanzengattung aus der Familie der Moschuskrautgewächse, (lateinischer Name): \"Sambucus nigra\" (zur Unterscheidung von [[blauer Holler]])"}]'::jsonb, 'Da schwoaze Holla is da echte Holunda, dea mit de Beean - da blaue Holla dageegn schaud hübsch aus, is owa a Fliida, und von dem kaunnst nix trinken!'),
  ('schwoaza-fliida', 'schwoaza Fliida', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'schwarzer Flieder', '[{"kategorie": "wörtlich", "text": "\"schwarzer Flieder\" (vom mittelniederdeutschen \"vlieder\"=\"Flieder\")"}, {"kategorie": "bot.", "text": "\"schwarzer Holunder\", [[schwarzer Holler]] (Pflanzengattung aus der Familie der Moschuskrautgewächse), (lateinischer Name): \"Sambucus nigra\" (die volkstümliche Bezeichnung \"schwarzer Flieder\" für \"Holunder\" [\"schwarzer Holler\"] ist noch heute weit verbreitet)"}]'::jsonb, ''),
  ('bei-uns-dahaam-soogd-ma-schwoaza-flieda-owa-gmaand-is-natialich-da-holla', 'Bei uns dahaam soogd ma ''schwoaza Flieda'' - owa gmaand is natialich da Holla!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Bei uns daheim sagt man ''schwarzer Flieder'' - aber gemeint ist natürlich der Holler!', '[{"kategorie": "wörtlich", "text": "\"Bei uns daheim nennen ihn alle ''schwarzer Flieder'' - aber jeder meint natürlich den Holler!\"  2. Bei uns daheim sagt kein Mensch ''Holunder'' - wir kennen den Strauch als ''schwarzer Flieder''!  3. Manche nennen ihn ''Holunder'', aber bei uns heißt er immer noch ''schwarzer Flieder'' – ein alter Name für eine vertraute Pflanze!"}]'::jsonb, 'schwoaza Fliida'),
  ('blaua-holla', 'blaua Holla', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'blauer Holler', '[{"kategorie": "wörtlich", "text": "\"blauer Holler\" (vom mittelhochdeutschen \"holer\"=\"Holler\")"}, {"kategorie": "bot.", "text": "\"blauer Holunder\", (lateinischer Name): \"Sambucus cerulea\" (Pflanzengattung aus der Familie der Moschuskrautgewächse)"}, {"kategorie": "hist.", "text": "\"gemeiner Flieder\" (Pflanzengattung aus der Familie der Ölbaumgewächse), (lateinischer Name): \"Syringa vulgaris\" (die volkstümliche Bezeichnung \"blauer Holler\" wird noch heute für den \"gemeinen Flieder\" verwendet, um diesen vom echten Holunder, \"dem schwarzen Holler\", auch begrifflich zu unterscheiden. Denn als der wundervoll duftende Flieder im 16. Jahrhundert nach Mitteleuropa gelangte, trugen sowohl der Holunderstrauch als auch der Fliederbusch denselben Namen, nämlich \"Holler\" bzw. \"Holunder\")"}]'::jsonb, 'Da schwoaze Holla is da echte Holunda, dea mit de Beean - da blaue Holla dageegn schaud hübsch aus, is owa a Fliida, und von dem kaunnst nix trinken!'),
  ('da-schwoaze-holla-is-da-echte-holunda-dea-mit-de-beean-da-blaue-holla-dageegn-schaud-huebsch-aus-is-owa-a-fliida-und-von-dem-kaunnst-nix-trinken', 'Da schwoaze Holla is da echte Holunda, dea mit de Beean - da blaue Holla dageegn schaud hübsch aus, is owa a Fliida, und von dem kaunnst nix trinken!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Der schwarze Holler is der echte Holunder, der mit den Beeren – der blaue Holler dagegen schaut hübsch aus, ist aber ein Flieder, und von dem kann man nix trinken!', '[{"kategorie": "wörtlich", "text": "\"Der schwarze Holler is der echte Holunder – der mit den Beeren zum Einkochen - der blaue Holunder dagegen ist nur ein schöner Flieder, aber zum Trinken taugt der nix!\"  2. Der schwarze Holler bringt Hollersaft, der blaue Holler dagegen schaut nur gut aus und duftet ein bisschen, ist in Wahrheit aber ein Flieder!  3. Hübsch blühen tun’s beide, aber trinken kannst nur vom schwarzen Holler – der blaue Holler ist nämlich ein Flieder!"}]'::jsonb, 'schwoaza Holla'),
  ('reed-kaan-holla-dahea', 'Reed kaan Holla dahea!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Rede keinen Holler daher!', '[{"kategorie": "wörtlich", "text": "\"Rede keinen Unsinn!\"  2. Erzähl keinen Stuss!  3. [[Reed]] kaan Schaas!  4. [[Reed]] kaan Zwiefä dahea!"}]'::jsonb, ''),
  ('reed-kaan-schduss-dahea', 'Reed kaan Schduss dahea!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Rede keinen Stuss daher!', '[{"kategorie": "wörtlich", "text": "\"Rede keinen Unsinn!\"  2. [[Reed]] kaan Holla dahea!  3. [[Reed]] kaan Schas!  4. Reed kaan Zwiefä dahea!"}]'::jsonb, ''),
  ('fia-den-holla-kriagst-kaan-groschn', 'Fia den Holla kriagst kaan Groschn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Für diesen Holler bekommst du keinen Groschen!', '[{"kategorie": "wörtlich", "text": "\"Für diesen Plunder bekommst du keinen Pfennig!\"  2. Für diesen Krempel zahl ich dir keinen Groschen!  3. Den werlosen Kram kannst du verschenken – kaufen tut das keiner!"}]'::jsonb, ''),
  ('des-is-a-volla-holla', 'Des is a volla Holla!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das ist ein voller Holler!', '[{"kategorie": "wörtlich", "text": "\"Das ist kompletter Unsinn!\"  2. Das ist totaler Quatsch!  3. Das ist absoluter Schwachsinn! 4. Das ist totaler [[Schmafu]]!"}]'::jsonb, ''),
  ('des-is-a-kompletta-holla', 'Des is a kompletta Holla!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das ist ein kompletter Holler!', '[{"kategorie": "wörtlich", "text": "\"Das ist kompletter Unsinn!\"  2. Das ist totaler Quatsch!  3. Das ist absoluter Schwachsinn! 4. Das ist totaler [[Schmafu]]!"}]'::jsonb, ''),
  ('schdoeoe-di-ned-so-hoppadaadschad-au-a-jeeda-depp-schofft-des', 'Schdöö di ned so hoppadaadschad au - a jeeda Depp schofft des!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Stell dich nicht so hoppertatschert an - ein jeder Depp schafft das!', '[{"kategorie": "wörtlich", "text": "\"Stell dich nicht so tollpatschig an - jeder Schwachkopf schafft das!\"  2. Tu nicht so ungeschickt – das kriegt sogar der letzte Depp hin!  3. Stell dich nicht so deppert an – das schafft sogar mein kleiner Neffe mit verbundenen Augen!"}]'::jsonb, ''),
  ('heast-oida-schdoeoe-di-ned-so-hoppadaadschich-au-a-jeeda-depp-schofft-des', 'Heast Oida, schdöö di ned so hoppadaadschich au - a jeeda Depp schofft des!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hör mal Alter, stell dich nicht so hoppertatschig an - ein jeder Depp schafft das!', '[{"kategorie": "wörtlich", "text": "\"Mensch, stell dich nicht so tollpatschig an - jeder Schwachkopf schafft das!\"  2. Junge, tu nicht so ungeschickt – das kriegt sogar der letzte Depp hin!  3. Hey, du [[Weh]], stell dich nicht so deppert an – das schafft sogar mein kleiner Neffe mit verbundenen Augen!"}]'::jsonb, ''),
  ('bei-dem-hoppadaadschadn-muassd-aungst-haum-dassa-iwad-eiganen-fiass-foid', 'Bei dem Hoppadaadschadn muassd Aungst haum, dassa iwad eiganen Fiass foid!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bei diesem Hoppertatscherten muss man Angst haben, dass er über die eigenen Füße fällt!', '[{"kategorie": "wörtlich", "text": "\"Bei diesem unbeholfenen Tollpatsch muss man Angst haben, dass er über seine eigenen Füße stolpert!\"  2. Bei diesem schusseligen Tölpel muss man darauf gefasst sein, dass er gleich über seine eigenen Beine stolpert!  3. Dieser Dillo kann im Stehen stolpern – jederzeit und ganz ohne Hilfe!"}]'::jsonb, ''),
  ('glaub-mas-bei-dem-hoppadaadschichn-muassd-aungst-haum-dassa-iwad-eiganen-fiass-foid', 'Glaub mas, bei dem Hoppadaadschichn muassd Aungst haum, dassa iwad eiganen Fiass foid!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Glaub mir''s, bei diesem Hoppertatschigen muss man Angst haben, dass er über die eigenen Füße fällt!', '[{"kategorie": "wörtlich", "text": "\"Glaub mir, bei diesem unbeholfenen Tollpatsch muss man Angst haben, dass er über seine eigenen Füße stolpert!\"  2. Ehrlich, bei diesem schusseligen Tölpel muss man darauf gefasst sein, dass er gleich über seine eigenen Beine stolpert!  3. Ich sag''s dir: Dieser Dillo kann im Stehen stolpern – jederzeit und ganz ohne Hilfe!"}]'::jsonb, ''),
  ('so-a-hoppala-kaunn-an-jeedn-moi-passian', 'So a Hoppala kaunn an jeedn moi passian!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'So ein Hoppala kann einem jeden mal passieren!', '[{"kategorie": "wörtlich", "text": "\"So ein kleines Missgeschick kann jedem mal passieren!\"  2. So ein kleiner Ausrutscher kann schon mal vorkommen!  3. Für diesen kleinen Fauxpas brauchst dich nicht zu genieren – sowas passiert jedem mal!"}]'::jsonb, ''),
  ('hoppala-do-hod-si-aana-iwanumman', 'Hoppala, do hod si aana iwanumman!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hoppala, da hat sich einer übernommen!', '[{"kategorie": "wörtlich", "text": "\"Oje, da hat sich jemand wohl übernommen!\"  2. Upsi, das war wohl ein bisschen zu ambitioniert!  3. Autsch, da hat jemand seine Fähigkeiten wohl falsch eingeschätzt!"}]'::jsonb, ''),
  ('hoppla-do-hod-si-aana-iwanumman', 'Hoppla, do hod si aana iwanumman!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hoppala, da hat sich einer übernommen!', '[{"kategorie": "wörtlich", "text": "\"Oje, da hat sich jemand wohl übernommen!\"  2. Upsi, das war wohl ein bisschen zu ambitioniert!  3. Autsch, da hat jemand seine Fähigkeiten wohl falsch eingeschätzt!"}]'::jsonb, ''),
  ('hoppsala-do-hod-si-aana-iwanumman', 'Hoppsala, do hod si aana iwanumman!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hoppala, da hat sich einer übernommen!', '[{"kategorie": "wörtlich", "text": "\"Oje, da hat sich jemand wohl übernommen!\"  2. Upsi, das war wohl ein bisschen zu ambitioniert!  3. Autsch, da hat jemand seine Fähigkeiten wohl falsch eingeschätzt!"}]'::jsonb, ''),
  ('hoppala-mochn', 'hoppala mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'hoppala machen', '[{"kategorie": "wörtlich", "text": "\"hoppala machen\" (vom französischen \"faire hop-l[[=]]einen Hopser machen\")"}, {"kategorie": "allg.", "text": "stolpern, stürzen, hinfallen, zu Boden fallen"}]'::jsonb, 'Da Klaane hod aum Glotteis hoppala gmochd - owa zum Glick is nix passiad!'),
  ('da-klaane-hod-aum-glotteis-hoppala-gmochd-owa-zum-glick-is-nix-passiad', 'Da Klaane hod aum Glotteis hoppala gmochd - owa zum Glick is nix passiad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Kleine hat am Glatteis hoppala gemacht - aber zum Glück ist nix passiert!', '[{"kategorie": "wörtlich", "text": "\"Der Kleine ist auf dem Glatteis ausgerutscht – aber zum Glück ist nichts passiert!\"  2. Der Kleine ist auf dem Eis gestürzt – aber zum Glück hat er sich nicht wehgetan!  3. Der Kleine hat sich auf dem Glatteis hingeplumpst – aber zum Glück war alles nur halb so wild!"}]'::jsonb, 'hoppala mochn'),
  ('i-loss-mi-ned-gean-hoeoeschaln-meak-da-des-aa-fia-olle-moi-oida', 'I loss mi ned gean hööschaln - meak da des aa fia olle Moi, Oida!', '', '', '', 'Wiener Gaunersprache', 'Ich lass mich nicht gern höscherln - merk dir das ein für alle Mal, Alter!', '[{"kategorie": "wörtlich", "text": "\"Ich lass mich nicht gern verarschen - merk dir das ein für alle Mal, Alter!\"  2. Verarsch mich nicht, Alter – ich mein’s ernst, kapiert?  3. Mach deine Spielchen mit wem anderen, Alter – bei mir ist Schluss, verstanden?"}]'::jsonb, ''),
  ('beim-hoeoeschaln-hoda-in-boin-easchd-noch-fuenf-minuutn-dawischd-und-fia-so-an-schbueuela-zoin-de-millionen', 'Beim Hööschaln hoda in Boin easchd noch fünf Minuutn dawischd - und fia so an Schbüüla zoin de Millionen!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Beim Höscherln hat er den Ball erst nach fünf Minuten erwischt - und für so einen Spieler zahlen die Millionen!', '[{"kategorie": "wörtlich", "text": "\"Bei der Trainingseinheit \"Ball-im-Kreis-Jagen\" hat er die Kugel erst nach fünf Minuten erwischt - und für so einen Spieler zahlt der Verein Millionen!\"  2. Beim ''Schweinchen-in-der-Mitte-Spiel'' hat der neue Spieler fünf Minuten lang nur Luft gesehen – und der soll Millionen wert sein?  3. Beim ''Rondo'' ist der neue Spieler fünf Minuten dem Ball nachgelaufen – und das soll unser Top-Transfer sein?"}]'::jsonb, ''),
  ('ea-is-kaa-profi-owa-a-echta-ballestara-jeede-wochn-schdeeda-mid-seine-haawara-aum-plotz', 'Ea is kaa Profi, owa a echta Ballestara - jeede Wochn schdeeda mid seine Haawara aum Plotz!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Er ist kein Profi, aber ein echter Ballesterer: jede Woche steht er mit seinen Haberern auf dem Platz!', '[{"kategorie": "wörtlich", "text": "\"Er ist kein Profi, aber ein echter Ballesterer: Woche für Woche steht er mit seinen Kumpels auf dem Platz!\"  2. Er spielt nicht in der Bundesliga, aber er lebt für den Fußball – jeden Sonntag steht er mit seinen Freunden am Platz!  3. Er kickt nicht für Geld, sondern fürs Bier danach – ein echter Ballesterer halt!"}]'::jsonb, ''),
  ('aum-sunndoog-findst-im-prooda-kaa-aanzige-wiesn-wo-ned-ballestad-wiad', 'Aum Sunndoog findst im Prooda kaa aanzige Wiesn, wo ned ballestad wiad!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Am Sonntag findest du im Prater keine einzige Wiese, wo nicht ballestert wird!', '[{"kategorie": "wörtlich", "text": "\"Am Sonntag findest du im Prater keine einzige Wiese, wo nicht Fußball gespielt wird!\"  2. Am Sonntag wird auf jeder Wiese im Prater gekickt – überall rollt der Ball!  3. Im Prater gehört der Sonntag dem Fußball – auf jeder Wiese wird ballestert!"}]'::jsonb, ''),
  ('bei-uns-in-da-u17-woas-noamal-wea-zspaeaed-kumma-is-hod-vom-traeaena-an-eisenbauna-kassiad', 'Bei uns in da U17 woas noamal - wea zspääd kumma is, hod vom Trääna an Eisenbauna kassiad!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Bei uns in der U17 war das normal: Wer zu spät gekommen ist, hat vom Trainer einen Eisenbahner kassiert!', '[{"kategorie": "wörtlich", "text": "\"Bei uns in der U17 war das normal: Wer zu spät kam, hat vom Trainer einen Kniestoß in den Hintern verpasst bekommen!\"  2. In unserer U17 war Pünktlichkeit Pflicht – wer’s nicht ernst nahm, bekam vom Trainer einen Kniestoß in den Oberschenkel!  3. U17 war hart – wer zu spät kam, fing sich vom Trainer gleich mal einen saftigen Eisenbahner ein!"}]'::jsonb, ''),
  ('a-waunsinn-mit-dem-eisnbauna-hod-a-glei-zwaa-obweaschbueuela-aufs-obschdoeoegleis-gschickd', 'A Waunsinn - mit dem Eisnbauna hod a glei zwaa Obweaschbüüla aufs Obschdöögleis gschickd!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Ein Wahnsinn - mit diesem Eisenbahner hat er gleich zwei Abwehrspieler auf’s Abstellgleis geschickt!', '[{"kategorie": "wörtlich", "text": "\"Unglaublich - mit dieser perfekten Körpertäuschung hat er gleich zwei Abwehrspieler ins Leere laufen lassen!\"  2. Mit einem einzigen Move hat er gleich zwei Gegenspieler ausgeschaltet – blitzsaubere Finte!  3. Brillant gemacht – zwei Mann aus dem Spiel genommen, ohne den Ball zu berühren!"}]'::jsonb, ''),
  ('banaanan-wochsn-auf-schdaudn-ghean-owa-zu-den-beeanfruechtn', 'Banaanan wochsn auf Schdaudn, ghean owa zu den Beeanfrüchtn!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Bananen wachsen auf Stauden, gehören aber zu den Beerenfrüchten!', '[{"kategorie": "wörtlich", "text": "\"Bananen wachsen an Stauden, zählen botanisch jedoch zu den Beeren!\"  2. Obwohl Bananen an Stauden wachsen, gelten sie aus botanischer Sicht als Beerenfrüchte!  3. Die Bananenpflanze ist eine Staude, doch ihre Früchte werden den Beeren zugeordnet!"}]'::jsonb, ''),
  ('banaanan-san-a-idealer-snaeck-fia-schbuatla-waeus-schnoeoe-energie-liefan', 'Banaanan san a idealer Snäck fia Schbuatla, wäus schnöö Energie liefan!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Bananen sind ein idealer Snack für Sportler, da sie schnell Energie liefern!', '[{"kategorie": "wörtlich", "text": "\"Dank ihrer leicht verdaulichen Kohlenhydrate sind Bananen ein optimaler Energiesnack für Sportler!\"  2. Bananen sind bei Sportlern beliebt, weil sie schnell Kraft liefern und gut verträglich sind!  3. Die Banane ist für Sportler, was der Sprit fürs Auto ist: schnell drin und gleich voll dabei!"}]'::jsonb, ''),
  ('min-aussnrist-hoda-a-peafekte-banaan-genau-aufn-oeoefapunkt-einedraad', 'Min Aussnrist hoda a peafekte Banaan genau aufn Ööfapunkt einedraad!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Mit dem Außenrist hat er eine perfekte Banane genau auf den Elferpunkt reingedreht!', '[{"kategorie": "wörtlich", "text": "\"Mit feinem Außenrist hat er die Flanke präzise auf den Elferpunkt gedreht – ein Traumpass mit vierl Effet!\"  2. Er malt mit dem Außenrist eine Kurve in die Luft – und der Ball senkt sich punktgenau auf den Elfmeterpunkt!  3. Der dreht den Ball mit dem Außenrist perfekt um den Abwehrspieler rum – und der Stürmer braucht am Elferpunkt nur noch den Kopf hinhalten!"}]'::jsonb, ''),
  ('ea-hoid-si-fia-an-kasanoova-dabei-schaud-sei-banaan-eeha-aus-wiara-vadoeate-fruchtwuazn', 'Ea hoid si fia an Kasanoova - dabei schaud sei Banaan eeha aus wiara vadöate Fruchtwuazn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Er hält sich für einen Casanova – dabei schaut seine Banane eher aus wie wie eine verdörrte Fruchtwurzen!', '[{"kategorie": "wörtlich", "text": "\"Er denkt, er ist ein Casanova – aber seine Banane wirkt eher wie eine verdörrte Frucht!\"  2. Er glaubt, er sei ein Frauenheld – aber sein Schniedel sieht aus wie ''ne verschrumpelte Banane!  3. Von außen der Macho – von unten der Gartenzwerg mit Spaghetti-Schwert!"}]'::jsonb, ''),
  ('ea-schdeed-genau-richtig-und-vasenkd-in-ooprolla-eiskoid-a-klassisches-ooschdaubagoi', 'Ea schdeed genau richtig und vasenkd in Ooprolla eiskoid - a klassisches Ooschdaubagoi!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Er steht genau richtig und versenkt den Abpraller eiskalt – ein klassischer Abstaubergoal!', '[{"kategorie": "wörtlich", "text": "\"Er steht genau richtig und macht ihn im Nachschuss rein – ein klassisches Abstaubertor!\"  2. Er steht genau dort, wo ein Knipser stehen muss, und stochert ihn kaltschnäuzig ins Tor - ein klassischer Abstauber!  3. Kaltschnäuzig, instinktsicher – der Rebound landet genau da, wo er steht: Abstauber-Goal wie aus dem Fußball-ABC!"}]'::jsonb, ''),
  ('so-an-knipsa-winschad-si-jeeda-traeaena-eiskoid-vuam-tiarl-und-imma-zua-schdoeoe', 'So an Knipsa winschad si jeeda Trääna - eiskoid vuam Tiarl und imma zua Schdöö!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'So einen Knipser würde sich jeder Trainer wünschen: eiskalt vor dem Tor und immer zur Stelle!', '[{"kategorie": "wörtlich", "text": "\"So einen Knipser wünscht sich jeder Trainer: eiskalt vor dem Tor und immer zur Stelle!\"  2. Jeder Coach träumt von so einem Torjäger – eiskalt im Abschluss und brandgefährlich im Strafraum!  3. So ein Knipser macht für jeden Trainer den Unterschied – eiskalt vor der Kiste und immer im richtigen Moment da!"}]'::jsonb, ''),
  ('i-bin-ka-proofi-eeha-so-a-knipsa-dea-beim-schbaziangee-ollas-meegliche-fotografiad', 'I bin ka Proofi - eeha so a Knipsa, dea beim Schbaziangee ollas Meegliche fotografiad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich bin kein Profi, eher so ein Knipser, der beim Spazierengehen alles Mögliche fotografiert!', '[{"kategorie": "wörtlich", "text": "\"Ich bin kein Profi, eher ein Hobbyfotograf, der beim Spazierengehen gerne Schnappschüsse macht!\"  2. Ich fotografiere nur aus Spaß – so als Freizeitknipser beim Spazierengehen!  3. Ich bin der Typ, der beim Gassigehen plötzlich eine Blume in Nahaufnahme fotografiert – ein klassischer Hobbyknipser!"}]'::jsonb, ''),
  ('im-reise-etui-hob-i-imma-an-klaan-knipsa-fiad-finganaeaegl-mit-dabei', 'Im Reise-Etui hob I imma an klaan Knipsa fiad Finganäägl mit dabei!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Im Reiseetui hab ich immer einen kleinen Knipser für die Fingernägel mit dabei!', '[{"kategorie": "wörtlich", "text": "\"In meinem Reiseetui habe ich immer einen kompakten Nagelknipser mit dabei!\"  2. In meinem Necessaire hab ich immer einen kleinen Nagelknipser griffbereit!  3. Der Mini-Knipser ist bei mir auf jeder Reise mit dabei!"}]'::jsonb, ''),
  ('hau-ma-aufd-eitriche-noo-an-gscheidn-schoafn-schbitz-drauf', 'Hau ma aufd Eitriche noo an gscheidn, schoafn Schbitz drauf!', '', '', '', 'Wiener Würstelstandjargon', 'Hau mir auf die Eitrige noch einen gescheiten, scharfen Spitz drauf!', '[{"kategorie": "wörtlich, Würstelstandjargon", "text": "\"Gib mir zur Käsekrainer noch einen spitzen, scharfen Pfefferoni!\"  2. Ich nehm ''ne Käsekrainer – und gib auch gleich ein scharfes Spitzerl dazu!  3. Gib mir zur Eitrigen noch einen scharfen Pfefferoni drauf - aber einen richtig feurigen Spitz, ned so a Larifariding!"}]'::jsonb, ''),
  ('a-schbitz-im-haus-is-wiara-leebende-alaamaunlog', 'A Schbitz im Haus is wiara leebende Alaamaunlog!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Ein Spitz im Haus ist wie ''ne lebende Alarmanlage!', '[{"kategorie": "wörtlich", "text": "\"Mit ’nem Spitz im Haus brauchst du keinen Bewegungsmelder mehr!\"  2. Der Spitz sieht klein aus, aber wenn er bellt, ist er lauter als jede Alarmsirene!  3. Ein Spitz? Der bellt schon, wenn ein Blatt im Garten landet!"}]'::jsonb, ''),
  ('waunn-bei-dem-da-schbitz-juckd-is-da-vaschdaund-auf-ualaub', 'Waunn bei dem da Schbitz juckd, is da Vaschdaund auf Ualaub!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Wenn bei dem der Spitz juckt, ist der Verstand auf Urlaub!', '[{"kategorie": "wörtlich", "text": "\"Wenn’s im Schritt kribbelt, hört bei dem das Denken auf!\"  2. Sobald bei dem unten was zuckt, schaltet oben alles ab!  3. Sobald der Schwanz juckt, ist beim Hirn Sendepause!"}]'::jsonb, ''),
  ('fia-an-schbitz-hob-i-mi-friara-imma-so-scheniad', 'Fia an Schbitz hob I mi friara imma so scheniad!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Für einen Spitz hab'' ich mich früher immer so geniert!', '[{"kategorie": "wörtlich", "text": "\"Für einen unkontrollierten Schuss mit der Schuhspitze habe ich mich früher immer so geniert!\"  [legendärer Ausspruch von Herbert Prohaska nach seinem Siegestor gegen die Türkei bei der WM-Quali 1978]"}, {"kategorie": "", "text": "Für einen Schuss mit der Pike habe ich mich früher immer so geschämt!  3. Früher war mir ein Schuss mit dem Spitz richtig peinlich!"}]'::jsonb, ''),
  ('des-mentsch-hod-ma-an-schbitz-in-oasch-geem-dass-i-drei-toog-ned-sitzn-hob-kennan', 'Des Mentsch hod ma an Schbitz in Oasch geem, dass I drei Toog ned sitzn hob kennan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das Mädchen hat mir einen Spitz in den Arsch verpasst, dass ich drei Tage nicht sitzen hab'' können!', '[{"kategorie": "wörtlich", "text": "\"Das Mädchen hat mich mit der Schuhspitze so hart in den Hintern getreten, dass ich drei Tage nicht sitzen konnte!\"  2. Das Mädchen hat mich mit der Schuhspitze voll in den Arsch getreten – seitdem brauch ich eine Sitzunterlage!  3. Die hat mir so eine mit der Schuhspitze reingetreten, dass ich drei Tage nicht sitzen konnte!"}]'::jsonb, ''),
  ('a-schee-greifda-gruschbaeschbitz-is-es-peafekte-fleisch-zum-siadn', 'A schee greifda Gruschbäschbitz is es peafekte Fleisch zum Siadn!', '', '', '', 'Wiener Fleischhauer-Slang', 'Ein schön gereifter Kruspelspitz ist das perfekte Fleisch zum Sieden!', '[{"kategorie": "wörtlich", "text": "\"Schön gereifter Kruspelspitz eignet sich hervorragend als Siedefleisch!\"  2. Ein gut marmorierter Kruspelspitz ist ideal für schonendes Sieden und bringt intensiven Geschmack!  3. Durch seinen Fettanteil ist Kruspelspitz perfekt für alle klassischen Siedegerichte!"}]'::jsonb, ''),
  ('sie-soogd-sei-gruschbaeschbitz-woa-wias-original-aus-da-fleischvitriin-waach-owa-gschmackig', 'Sie soogd, sei Gruschbäschbitz woa wias Original aus da Fleischvitriin - waach, owa gschmackig!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sie sagt, sein Kruspelspitz war wie das Original aus der Fleischvitrine – weich, aber g’schmackig!', '[{"kategorie": "wörtlich", "text": "\"Sie sagt, sein Schniedel war wie ''ne ausgelöste Zwischenrippe aus der Fleischtheke – weich, aber g’schmackig!\"  2. Sie sagt, sein Zipferl war wie ein Kruspelspitz: butterweich, aber würzig!  3. Sie sagt, sein Spatzerl war weich, aber g’schmackig – wie ein schön greifter Kruspelspitz!"}]'::jsonb, ''),
  ('easchd-de-gruschbae-mochds-fleisch-so-richtig-gschmackig-und-softig', 'Easchd de Gruschbä mochds Fleisch so richtig gschmackig und softig!', '', '', '', 'Wiener Fleischhauer-Slang', 'Erst die Kruspel macht das Fleisch so richtig g’schmackig und saftig!', '[{"kategorie": "wörtlich", "text": "\"Erst die Schwarte macht das Fleisch so richtig g’schmackig und saftig!\"  2. Erst das [[Schwartl]] sorgt für Saft und Aroma – ohne wär das Fleisch nur halb so gut!  3. Der Fettdeckel bringt Geschmack – erst durch die Schwarte wird’s ein richtiger Braten!"}]'::jsonb, ''),
  ('aussn-gruschbaeds-owa-innan-zoat-und-softig-genauso-muass-a-schweinsbraadl-sei', 'Aussn gruschbäds, owa innan zoat und softig - genauso muass a Schweinsbraadl sei!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Außen kruspelt’s, aber innen zart und saftig – genau so muss ein Schweinsbraten sein!', '[{"kategorie": "wörtlich", "text": "\"Außen knusprig, innen butterzart und saftig– so schmeckt ein echter Schweinsbraten!\"  2. Außen resch, innen zart – besser kann ein Schweinsbraten nicht sein!  3. Knusperkruste trifft auf saftiges Fleisch – ein Braten, wie man ihn sich wünscht!"}]'::jsonb, 'Wiina Schweinsbraadl'),
  ('duach-sei-grobe-struktua-bleibd-da-kavaliaschbitz-beim-kochn-schee-softig-und-aromatisch', 'Duach sei grobe Struktua bleibd da Kavaliaschbitz beim Kochn schee softig und aromatisch!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Durch seine grobe Struktur bleibt der Kavalierspitz beim Kochen schön saftig und aromatisch!', '[{"kategorie": "wörtlich", "text": "\"Dank seiner grobfaserigen Struktur behält der Kavalierspitz beim Garen seine Saftigkeit und sein volles Aroma!\"  2. Die ausgeprägte Faserung sorgt dafür, dass der Kavalierspitz auch nach langem Kochen zart und geschmackvoll bleibt!  3. Seine feste, durchwachsene Struktur macht den Kavalierspitz ideal für schonendes Schmoren und Sieden!"}]'::jsonb, ''),
  ('da-schuitaschbitz-is-vueue-faasriga-ois-da-toofaeschbitz-hod-dafia-owa-aa-mea-eigngschmock', 'Da Schuitaschbitz is vüü faasriga ois da Toofäschbitz, hod dafia owa aa mea Eigngschmock!', '', '', '', 'Wiener Fleischhauer-Slang', 'Der Schulterspitz ist viel faseriger als der Tafelspitz, hat dafür aber auch mehr Eigengeschmack!', '[{"kategorie": "wörtlich", "text": "\"Der Schulterspitz ist deutlich faseriger als der Tafelspitz, bringt aber auch mehr Eigengeschmack mit!\"  2. Im Vergleich zum feinfaserigen Tafelspitz hat der Schulterspitz eine deutlich gröbere Struktur, dafür aber auch einen intensiveren Eigengeschmack!  3. Der Schulterspitz ist zwar fester im Biss als der Tafelspitz, überzeugt aber durch sein kräftigeres Aroma!"}]'::jsonb, ''),
  ('graadfleisch-is-a-grobfasrigs-schdickl-aus-da-innaren-rindsschuita-ideal-zum-siadn', 'Graadfleisch is a grobfasrigs Schdickl aus da innaren Rindsschuita - ideal zum Siadn!', '', '', '', 'Wiener Fleischhauer-Slang', 'Gratfleisch ist ein grobfaseriges Stück aus der inneren Rinderschulter – ideal zum Sieden!', '[{"kategorie": "wörtlich", "text": "\"Gratfleisch ist ein grobfaseriges Stück von der Innenseite der Rinderschulter – ideal zum Sieden!\"  2. Gratfleisch ist ein grob strukturiertes Teilstück aus der inneren Rinderschulter, das sich hervorragend zum Sieden eignet!  3. Gratfleisch stammt aus dem unteren Schulterbereich des Rindes und ist aufgrund seiner Faserung ideal für langsames Sieden im eigenen Sud!"}]'::jsonb, ''),
  ('aum-schdaummtisch-deafs-oioobndliche-bomootschal-natialich-ned-foeoen', 'Aum Schdaummtisch deafs oioobndliche Bomootschal natialich ned föön!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Am Stammtisch darf das allabendliche Bonmotscherl natürlich nicht fehlen!', '[{"kategorie": "wörtlich", "text": "\"Am Stammtisch darf allabendlich ein schlagfertiger Spruch natürlich nicht fehlen!\"  2. Der allabendliche Stammtisch lebt von den geistreichen Bemerkungen seiner Gäste, die einen noch zu Hause lachen lassen!  3. Am Stammtisch wird palavert und philosophiert – und irgendwann fällt das obligatorische Bonmotscherl!"}]'::jsonb, ''),
  ('weas-gean-softig-und-deftig-mog-dea-greifd-zum-zweachschbitz-a-echta-geheimtipp-fia-rindfleischliibhoowa', 'Weas gean softig und deftig mog, dea greifd zum Zweachschbitz - a echta Geheimtipp fia Rindfleischliibhoowa!', '', '', '', 'Wiener Fleischhauer-Slang', 'Wer’s gern saftig und deftig mag, der greift zum Zwerchspitz – ein echter Geheimtipp für Rindfleischliebhaber!', '[{"kategorie": "wörtlich", "text": "\"Für alle, die kräftiges, saftiges Rindfleisch schätzen, ist der Zwerchspitz eine wahre Entdeckung!\"  2. Zwerchspitz – das ideale Stück für alle, die beim Rindfleisch auf echten Geschmack setzen!  3. Wem Tafelspitz zu fein ist, der findet im Zwerchspitz ein rustikales, geschmackvolles Gegenstück!"}]'::jsonb, ''),
  ('dicka-schbitz', 'Dicka Schbitz', 'der', '', '', 'Wiener Fleischhauer-Slang', 'Dicker Spitz', '[{"kategorie": "wörtlich", "text": "\"Dicker Spitz\" (Determinativkompositum aus \"dick\"=\"fest\" und \"Spitz\"=\"spitz zulaufendes Teilstück vom Rind\")"}, {"kategorie": "Fleischerjargon", "text": "\"saftiges Rinderteilstück von der sogenannten Platte im Vorderviertel unterhalb der Schulter\", \"Plattenstück vom Rind\",  [[Zweachschbitz]], [[Baafleisch]]"}]'::jsonb, 'A echta Geheimtipp fia Rindfleischliibhoowa: da dicke Schbitz - fia olle, dees gean softig und deftig meeng!'),
  ('a-echta-geheimtipp-fia-rindfleischliibhoowa-da-dicke-schbitz-fia-olle-dees-gean-softig-und-deftig-meeng', 'A echta Geheimtipp fia Rindfleischliibhoowa: da dicke Schbitz - fia olle, dees gean softig und deftig meeng!', '', '', '', 'Wiener Fleischhauer-Slang', 'Ein echter Geheimtipp für Rindfleischliebhaber: der ''Dicke Spitz'' - für alle, die''s gern saftig und deftig mögen!', '[{"kategorie": "wörtlich", "text": "\"Für alle, die kräftiges, saftiges Rindfleisch schätzen, ist der ''Dicke Spitz'' eine wahre Entdeckung!\"  2. ''Dicker Spitz'' – das ideale Stück für alle, die beim Rindfleisch auf echten Geschmack setzen!  3. Wem Tafelspitz zu fein ist, der findet im ''Dicken Spitz'' ein rustikales, geschmackvolles Gegenstück!"}]'::jsonb, ''),
  ('mit-an-doppae-driiwaschdeiga-hoda-sein-geegnschbueuela-ind-garaasch-gschickd', 'Mit an Doppä-Driiwaschdeiga hoda sein Geegnschbüüla ind Garaasch gschickd!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Mit einem Doppel-Drübersteiger hat er seinen Gegenspieler in die Garage geschickt!', '[{"kategorie": "wörtlich", "text": "\"Mit einem Doppel-Übersteiger hat er seinen Gegenspieler ins Leere laufen lassen!\"  2. Mit zwei schnellen Übersteigern hat er seinen Gegenspieler komplett stehen gelassen!  3. Technisch brillant: Zwei Übersteiger und der Weg zum Tor war frei!"}]'::jsonb, ''),
  ('dea-schdueama-hod-an-radius-wiara-biadeckl', 'Dea Schdüama hod an Radius wiara Biadeckl!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der Stürmer einen Radius wie ein Bierdeckel!', '[{"kategorie": "wörtlich, Fußballerjargon", "text": "\"Der Stürmer hat einen Aktionsradius von nicht mal einem Quadratmeter - lauffaul bis zum Gehtnichtmehr!\"  2. Der Stürmer bewegt sich ja kaum von der Stelle!  3. Der Stürmer steht da wie ein Hydrant - bewegen tut sich der nur, wenn''s Freibier gibt!"}]'::jsonb, ''),
  ('da-koeoena-hod-an-radius-wiara-biafueuez', 'Da Kööna hod an Radius wiara Biafüüz!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der Kellner einen Radius wie ein Bierfilz!', '[{"kategorie": "wörtlich", "text": "\"Der Kellner hat einen Aktionsradius von nicht mal einem Quadratmeter - lauffaul bis zum Gehtnichtmehr!\"  2. Der Kellner bewegt sich ja kaum von der Stelle!  3. Der Kellner steht da wie ein Hydrant - bewegen tut sich der nur, wenn''s Freibier gibt!"}]'::jsonb, ''),
  ('mei-oida-hod-an-radius-wiara-biatatzal', 'Mei Oida hod an Radius wiara Biatatzal!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Mein Alter hat einen Radius wie ein Biertatzerl!', '[{"kategorie": "wörtlich", "text": "\"Mein Alter hat einen Aktionsradius von nicht mal einem Quadratmeter - der ist lauffaul bis zum Gehtnichtmehr!\"  2. Mein Mann bewegt sich kaum von der Couch runter!  3. Mein Alter steht rum wie ein Hydrant - bewegen tut sich der nur, wenn''s Freibier gibt!"}]'::jsonb, ''),
  ('in-dem-bett-do-hauma-an-radius-wiara-biatoella', 'In dem Bett do hauma an Radius wiara Biatölla!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'In diesem Bett da haben wir einen Radius wie ein Biertteller!', '[{"kategorie": "wörtlich", "text": "\"In diesem Bett da haben wir einen Aktionsradius von nicht mal einem Quadratmeter!\"  2. In dem kleinen Bett da können wir beide uns nicht einmal umdrehen - geschweige denn schnackseln!  3. In diesem kleinen Bett haben wir zum Schnackseln so viel Platz wie auf einem Bierteller!"}]'::jsonb, ''),
  ('wem-in-da-hoeoeschn-haum', 'wem in da Hööschn haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden in der Hösche haben', '[{"kategorie": "wörtlich", "text": "\"jemanden in der Mangel haben\""}, {"kategorie": "", "text": "\"jemanden im Kreis laufen lassen\""}, {"kategorie": "", "text": "\"jemanden am Haken haben\""}, {"kategorie": "", "text": "\"mit jemandem Katz und Maus spielen\""}]'::jsonb, 'Beim Untasuchungsausschuss haums eam in da Hööschn ghobd - fünf Schdund laung hoda olle Froong geduidig beauntwuatn miassn!'),
  ('beim-untasuchungsausschuss-haums-eam-in-da-hoeoeschn-ghobd-fuenf-schdund-laung-hoda-olle-froong-geduidig-beauntwuatn-miassn', 'Beim Untasuchungsausschuss haums eam in da Hööschn ghobd - fünf Schdund laung hoda olle Froong geduidig beauntwuatn miassn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Beim Untersuchungsaausschuss haben sie ihn in der Hösche gehabt - fünf Stunden lang hat er alle Fragen geduldig beantworten müssen!', '[{"kategorie": "wörtlich", "text": "\"Beim Untersuchungsaausschuss haben sie ihn in der Mangel gehabt - fünf Stunden lang hat er alle Fragen geduldig beantworten müssen!\"  2. Beim Untersuchungsausschuss wurde er stundenlang ins Kreuzverhör genommen – fünf Stunden musste er Rede und Antwort stehen!  3. Im Untersuchungsausschuss haben sie ihn am Haken gehabt und systematisch gegrillt - fünf Stunden lang wurde er befragt, es gab kein Entkommen!"}]'::jsonb, 'wem in da Hööschn haum'),
  ('wem-im-hoeoeschal-haum', 'wem im Hööschal haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden im Höscherl haben', '[{"kategorie": "wörtlich", "text": "\"jemanden in der Mangel haben\""}, {"kategorie": "", "text": "\"jemanden im Kreis laufen lassen\""}, {"kategorie": "", "text": "\"jemanden am Haken haben\""}, {"kategorie": "", "text": "\"mit jemandem Katz und Maus spielen\""}]'::jsonb, 'De Kiewara haum eam im Höscherl - seit zwaa Toog wiada pausenlos vahöad!'),
  ('de-kiewara-haum-eam-im-hoescherl-seit-zwaa-toog-wiada-pausenlos-vahoead', 'De Kiewara haum eam im Höscherl - seit zwaa Toog wiada pausenlos vahöad!', '', '', '', 'Wiener Gaunersprache', 'Die Kieberer haben ihn im Höscherl - seit zwei Tagen wird er pausenlos verhört!', '[{"kategorie": "wörtlich", "text": "\"Die Bullen haben ihn in der Mangel - seit zwei Tagen wird er pausenlos verhört!\"  2. Die Polizei hat ihn am Wickel – und lässt seit zwei Tagen nicht locker!  3. Er hängt in der Verhörschleife – die Bullen pressen ihn seit zwei Tagen aus wie ’ne Zitrone!"}]'::jsonb, 'wem im Hööschal haum'),
  ('dea-barkiipa-hod-ma-in-bestn-hugo-gmixd-den-i-je-trunkn-hob', 'Dea Barkiipa hod ma in bestn Hugo gmixd, den I je trunkn hob!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Dieser Barkeeper hat mir den besten Hugo gemixt, den ich je getrunken hab!', '[{"kategorie": "wörtlich", "text": "\"Der Barkeeper hat mir den besten Hugo gemacht, den ich je hatte!\"  2. Der Barkeeper versteht sein Handwerk – dieser Hugo war ein Meisterwerk im Glas!  3. Ein perfekt balancierter Hugo – wohl der beste, der mir je serviert wurde!"}]'::jsonb, ''),
  ('da-blaade-sitzt-a-schdund-laung-aum-hugo-da-kloodeckl-hod-sicha-schoo-doeoen', 'Da Blaade sitzt a Schdund laung aum Hugo - da Kloodeckl hod sicha schoo Döön!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Blade sitzt eine Stunde lang am Hugo - der Klodeckel hat sicher schon Dellen!', '[{"kategorie": "wörtlich", "text": "\"Der Dicke sitzt eine Stunde lang im Klosett - der Klodeckel hat sicher schon Dellen!\"  2. Der Fettwanst sitzt eine Stunde lang am Porzellanthron - der Klodeckel ist sicher schon eingedrückt!  3. Wenn der Fette wieder eine Stunde auf’m Hugo hockt, brauchen wir bald einen neuen Klodeckel!"}]'::jsonb, ''),
  ('dea-rennd-mit-aana-so-engan-hoosn-umanaund-dassd-glaubsd-sei-hugo-winkt-schoo-ausse', 'Dea rennd mit aana so engan Hoosn umanaund, dassd glaubsd, sei Hugo winkt schoo ausse!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der rennt mit einer so engen Hose herum, dass du glaubst, sein Hugo winkt schon raus!', '[{"kategorie": "wörtlich", "text": "\"Er rennt mit so einer engen Hose herum, dass man glaubt, sein Schniedel winkt schon raus!\"  2. Bei dem engen Outfit glaubt man, sein [[Zumpferl]] macht gleich Männchen!  3. Da brauchst keine Röntgenbrille – sein Hugo grüßt schon durch den Stoff!"}]'::jsonb, ''),
  ('jo-ee-de-koeoenarin-is-a-bombn-owa-si-schdroid-so-an-gewissn-hugo-aus-waunnsd-waassd-wos-i-maan', 'Jo ee, de Köönarin is a Bombn, owa si schdroid so an gewissn Hugo aus - waunnsd waassd, wos I maan!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Ja eh, die Kellnerin ist eine Bombe, aber sie strahlt so einen gewissen Hugo aus - wenn du weißt, was ich meine!', '[{"kategorie": "wörtlich", "text": "\"Ja eh, die Kellnerin ist eine Bombe, aber sie strahlt so einen gewisse Anrüchigkeit aus - wenn du weißt, was ich meine!\"  2. Ja eh, die Kellnerin schaut super aus, aber sie hat ein bisschen was Verruchtes an sich – du verstehst schon!  3. Die Kellnerin ist definitiv ein Hingucker, doch sie hat dieses gewisse verruchte Etwas - wenn du weißt, was ich meine!"}]'::jsonb, ''),
  ('do-hods-an-hugo-wia-auf-aan-baunhofsheisl', 'Do hods an Hugo wia auf aan Baunhofsheisl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Da hat es einen Hugo wie auf einem Bahnhofshäusel', '[{"kategorie": "wörtlich", "text": "\"Da hat es einen strengen Geruch wie in einer Bahnhofstoilette!\"  2. Da stinkt''s wie in einem Bahnhofsklo!  3. Hier stinkt''s wie im Arsch eines Obdachlosen!"}]'::jsonb, ''),
  ('dass-es-wueued-peafekt-greifd-is-meakst-aum-siasslichn-fost-metallischn-hugo', 'Dass es Wüüd peafekt greifd is, meakst aum siasslichn, fost metallischn Hugo!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Dass das Wild perfekt gereift ist, merkst du am süßlichen, fast metallischen Haut-Goût!', '[{"kategorie": "wörtlich", "text": "\"Die perfekte Reife des Wilds erkennst du an der feinen, leicht süßlichen Note mit einem Hauch von Metall – dem klassischen Haut-Goût!\"  2. Das Fleisch duftet nach vollendeter Reife – mit einer eleganten Süße und metallischem Unterton, wie ihn nur feines Wildbret entwickelt!  3. Der dezente Haut-Goût, leicht süß und mineralisch, verrät: Dieses Wild wurde mit Geduld und Sorgfalt gereift!"}]'::jsonb, ''),
  ('zum-hugo-wean', 'zum Hugo wean', '', '', '', 'Wiener Sprüche, die sitzen!', 'zum Hugo werden', '[{"kategorie": "wörtlich", "text": "\"zur Lachnummer werden\" ([hist.]: „Hugo“ als Spottname für unfähige Rekruten der preußischen Armee)"}, {"kategorie": "", "text": "\"zum Gespött der Leute werden\""}, {"kategorie": "fig.", "text": "verrückt werden, den Verstand verlieren"}]'::jsonb, 'Mit dia wea I noo zum Hugo!'),
  ('mit-dia-wea-i-noo-zum-hugo', 'Mit dia wea I noo zum Hugo!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Mit dir werde ich noch zum Hugo!', '[{"kategorie": "wörtlich", "text": "\"Mit dir werde ich noch zur Lachnummer!\"  2. Mit dir werde ich zum Gespött der Leute!  3. (fig.) Mit dir verliere ich noch den Verstand!  4. Mit dir lande ich noch in der Klapsmühle!"}]'::jsonb, ''),
  ('fian-hugo', 'fian Hugo', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'für''n Hugo', '[{"kategorie": "wörtlich", "text": "\"für den Hugo\" (aus der Studentensprache des 19. Jahrhunderts, wo \"Hugo\" als Platzhaltername für etwas Belangloses bzw. \"Mr. Nobody\" [\"ein Nichts und Niemand\"] galt)"}, {"kategorie": "allg.", "text": "sinnlos, zwecklos, umsonst, vergebens, [[für]] die Katz, [[fian]] Oasch, [[fiad]] Jetti-Tant, [[fiad]] Wiaschd, [[fiad]] Fisch"}]'::jsonb, 'Des Gaunze woa fian Hugo!'),
  ('des-gaunze-woa-fian-hugo', 'Des Gaunze woa fian Hugo!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das Ganze war für''n Hugo!', '[{"kategorie": "", "text": "Das Ganze war [[für]] die Katz!  2. Das Ganze war völlig umsonst!  3. Das Ganze war vergeudete Mühe!  4. Das Ganze war für die [[Jetti-Tant]]!"}]'::jsonb, ''),
  ('de-blonde-aubroodn-is-fian-hugo-de-is-zaach-wiara-schuachsoin', 'De Blonde aubroodn is fian Hugo - de is zaach wiara Schuachsoin!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die Blonde anzubraten, ist für''n Hugo - die ist so zäh wie ''ne Schuhsohle!', '[{"kategorie": "wörtlich", "text": "\"Die Blonde anzubaggern, ist vergeudete Mühe - die ist so zäh wie ''ne Schuhsohle!\"  2. Die Blonde anzubaggern bringt nix – die lässt jeden Mann eiskalt abtropfen!  3. Die Blonde heiß zu machen, ist verschwendete Energie – die taut nicht mal im Hochsommer auf!"}]'::jsonb, 'fian Hugo'),
  ('i-foa-ind-hueuesn', 'I foa ind Hüüsn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich fahre in die Hülse!', '[{"kategorie": "wörtlich", "text": "\"Ich schlüpfe in meine äußere Hülle!\"  2. Ich schmeiß mich in die Klamotten!  3. Ich werfe mich in meine Kleidung!  4. [[I hau mi ins Gwaund!]]"}]'::jsonb, 'I hau mi ins Gwaund!'),
  ('i-hau-mi-ins-gwaund', 'I hau mi ins Gwaund!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich haue mich ins Gewand!', '[{"kategorie": "wörtlich", "text": "\"Ich werfe mich in mein Gewand!\"  2. Ich schmeiß mich in die Klamotten!  3. Ich schlüpfe in meine äußere Hülle!  4. [[I foa ind Hüüsn!]]"}]'::jsonb, 'I foa ind Hüüsn!'),
  ('si-troogd-zwoa-a-teire-hueuesn-owa-heaz-und-hian-hods-kaans', 'Si troogd zwoa a teire Hüüsn, owa Heaz und Hian hods kaans!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sie trägt zwar eine teure Hülse, aber Herz und Hirn hat sie keins!', '[{"kategorie": "wöertlich", "text": "\"Sie hüllt sich von Kopf bis Fuß  in teure Markenkleidung, doch Herz und Hirn hat sie nicht!\"  2. Hülle hui, Inhalt pfui!  3. Ihre äußere Hülle besteht aus eleganten Designerklamotten, aber innerlich fehlt es ihr an Empathie und Verstand!"}]'::jsonb, ''),
  ('mit-so-aana-hueuesn-aum-schaeaedl-foisd-sogoa-im-ziakus-auf', 'Mit so aana Hüüsn aum Schäädl foisd sogoa im Ziakus auf!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mit so einer Hülse auf’m Schädel fällst du sogar im Zirkus auf!', '[{"kategorie": "wörtlich", "text": "\"Mit so einem Hut am Kopf fällst du sogar im Zirkus auf!\"  2. Der Hut ist so extravagant, damit würdest du auch im Zirkus auffallen!  3. In dem Zylinder siehst du aus wie ’ne Mischung aus Zirkus und Opernball – nur falschrum!"}]'::jsonb, ''),
  ('hau-da-ned-z-vueue-eine-iagendwaunn-mochd-de-hueuesn-dicht', 'Hau da ned z''vüü eine - iagendwaunn mochd de Hüüsn dicht!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Hau dir nicht zu viel rein - irgendwann macht die Hülsen dicht!', '[{"kategorie": "wörtlich", "text": "\"Schütt dir nicht zu viel rein – irgendwann macht dein Schädel zu!\"  2. Kipp dir noch mehr rein, und dein Kopf gibt komplett den Geist auf!  3. Wenn du so weitermachst, fährt dir das Hirn runter!"}]'::jsonb, ''),
  ('waunnd-eabsnfrucht-reif-is-geed-d-hueuesn-auf-und-gibd-de-sauman-fei', 'Waunnd Eabsnfrucht reif is, geed d''Hüüsn auf und gibd de Sauman fei!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Wenn die Erbsenfrucht reif ist, geht die Hülse auf und gibt die Samen frei!', '[{"kategorie": "wörtlich", "text": "\"Wenn die Erbsenfrucht reif ist, öffnet sich die Hülse entlang ihrer Nähte und gibt die Samen frei!\"  2. Nach Abschluss der Samenreife spaltet sich die Hülse und setzt die Erbsensamen frei!  3. Sobald sie reif ist, platzt die Hülse der Erbsenfrucht auf und streut ihre Samen aus!"}]'::jsonb, ''),
  ('si-aan-ind-hueuesn-haun', 'si aan ind Hüüsn haun', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich einen in die Hülsen hauen', '[{"kategorie": "wörtlich", "text": "\"sich einen hinter die Binde kippen\""}, {"kategorie": "", "text": "[[sich einen in die Figur stoßen]]"}, {"kategorie": "", "text": "[[sich einen hinter die Kulissen schieben]]"}]'::jsonb, 'Oida, jetzt is Feiaoobnd - hau ma uns an ind Hüüsn!'),
  ('oida-jetzt-is-feiaoobnd-hau-ma-uns-an-ind-hueuesn', 'Oida, jetzt is Feiaoobnd - hau ma uns an ind Hüüsn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Alter, jetzt ist Feierabend - hauen wir uns einen in die Hülse!', '[{"kategorie": "wörtlich", "text": "\"Alter, jetzt ist Feierabend - kippen wir uns einen hinter die Binde!\"  2. Feierabend, Kumpel – jetzt knallen wir uns einen rein!  3. Genug geschuftet, Alter – jetzt schieben wir uns einen hinter die Kulissen!"}]'::jsonb, 'si aan ind Hüüsn haun'),
  ('volle-hueuesn', 'Volle Hüüsn!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Volle Hülse!', '[{"kategorie": "wörtlich", "text": "\"Volle Kanne!\" (Ausruf, der starke, begeisterte Zustimmung ausdrückt)  2. \"Voll Stoff!\"  3. \"Volles Brett!\""}]'::jsonb, '"Woas Konzeat geil?" - "Oida, volle Hüüsn!"'),
  ('reib-ume-a-hueuesn', 'Reib ume a Hüüsn!', '', '', '', 'Wiener Würstelstandjargon', 'Reib rüber eine Hülse!', '[{"kategorie": "wörtlich", "text": "\"Rück eine Flasche Bier raus!\"  2. (Würstelstand): \"Gib her eine Halbliterdose Bier!\"  3. \"Reich mir ''ne Bierflasche rüber!\""}]'::jsonb, ''),
  ('hueuesn-oda-gloosweckal', 'Hüüsn oda Gloosweckal?', '', '', '', 'Wiener Würstelstandjargon', 'Hülse oder Glasweckerl?', '[{"kategorie": "Würstelstandjargon, scherzhaft für", "text": "\"Dose oder Flasche?\" (die Standardfrage am Wiener Würstelstand)"}, {"kategorie": "", "text": "\"Dosen- oder Flaschenbier?\"  3. \"Bier aus der Dose oder Flasche?\""}]'::jsonb, ''),
  ('sie-hussn-de-oaman-leit-ausn-duaf', 'Sie hussn de oaman Leit ausn Duaf!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Sie hussen die armen Leut aus dem Dorf!', '[{"kategorie": "wörtlich, hist.", "text": "\"Sie jagen die armen Leute aus dem Dorf!\" (vom mittelhochdeutschen \"hussen\"=\"jemanden wie einen Ketzer behandeln\" - abgeleitet vom Namen des Reformators Jan Hus († 1415), nach dessen Verurteilung und Hinrichtung als Ketzer [durch das Konzil von Konstanz] seine Anhänger, die sogenannten Hussiten, verfolgt wurden)"}, {"kategorie": "", "text": "Sie verstoßen die Armen aus dem Dorf!  3. Sie vertreiben die armen Menschen aus dem Dorf wie Aussätzige!"}]'::jsonb, ''),
  ('tua-ned-hussn', 'Tua ned hussn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Tu nicht hussen!', '[{"kategorie": "wörtlich", "text": "\"Tu nicht hetzen!\"  2. \"Schür keinen Aufruhr!\"  3. \"Hör auf, Leute aufzustacheln!\"  4. \"Hetze nicht gegen andere!\"  5. \"Hör auf zu stänkern!\""}]'::jsonb, ''),
  ('i-wueue-jo-ned-hussn-owa-waunn-blaeaedheid-blian-kennd-warad-des-do-a-botanischa-goatn', 'I wüü jo ned hussn, owa waunn Bläädheid blian kennd, warad des do a botanischa Goatn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich will ja nicht hussen, aber wenn Dummheit blühen könnte, wär das hier ein botanischer Garten!', '[{"kategorie": "wörtlich", "text": "\"Ich möchte keinen Aufruhr schüren, aber wenn Dummheit blühen könnte, wär das hier ein botanischer Garten!\"  2. Ich will ja nix sagen, aber so viel geballte Ahnungslosigkeit braucht ein eigenes Warnschild!  3. Ohne hussen zu wollen, aber wenn Dämlichkeit leuchten würde, wär das hier ein Flutlichtstadion!"}]'::jsonb, ''),
  ('i-hau-mi-jetzt-ind-huutschn', 'I hau mi jetzt ind Huutschn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich hau mich jetzt in die Hutschen!', '[{"kategorie": "wörtlich", "text": "\"Ich leg mich jetzt ins Bett!\"  2. [[Ich]] schmeiß mich jetzt in die Heija!  3. [[Ich]] hau mich jetzt in die Harpfen!"}]'::jsonb, ''),
  ('i-hau-mi-jetzt-ind-haapfn', 'I hau mi jetzt ind Haapfn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich hau mich jetzt in die Harpfen!', '[{"kategorie": "wörtlich", "text": "\"Ich leg mich jetzt ins Bett!\"  2. [[Ich]] schmeiß mich jetzt in die Heija!  3. [[Ich]] hau mich jetzt in die [[Hutschen]]!"}]'::jsonb, ''),
  ('i-schmeiss-mi-jetzt-ind-heija', 'I schmeiss mi jetzt ind Heija!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich schmeiß mich jetzt in die Heija!', '[{"kategorie": "wörtlich", "text": "\"Ich leg mich jetzt ins Bett!\"  2. [[Ich]] hau mich jetzt in die [[Hutschen]]!  3. [[Ich]] hau mich jetzt in die Harpfen!"}]'::jsonb, ''),
  ('auf-aana-huutschn-fueuel-i-mi-wieda-wiara-klaans-kind', 'Auf aana Huutschn füül I mi wieda wiara klaans Kind!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Auf einer Hutschen fühl ich mich wieder wie ein kleines Kind!', '[{"kategorie": "wörtlich", "text": "\"Auf der Schaukel fühle ich mich wieder wie ein kleines Kind!\"  2. Wenn ich auf der Schaukel sitze, werde ich wieder zum Kind!  3. Das Schaukeln erinnert mich daran, wie es war, ein Kind zu sein!"}]'::jsonb, ''),
  ('de-huutschn-is-oizeit-bereit-foeoed-nua-no-aana-deas-auschiabd', 'De Huutschn is oizeit bereit - fööd nua no aana, deas auschiabd!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die Hutschen ist allzeit bereit - fehlt nur noch einer, der sie anschiebt!', '[{"kategorie": "wörtlich", "text": "\"Dieses Frauenzimmer ist allzeit bereit - fehlt nur noch einer, der sie anschiebt!\"  2. Dieses Weib ist wie eine Hutsche auf dem Rummelplatz – bereit für jeden, der sie anschiebt!  3. Dieses Weibsbild ist bereit wie ’ne Wippe im Park – fehlt nur noch einer, der anschiebt!"}]'::jsonb, ''),
  ('da-huutschnschleidara-hod-scho-wiida-a-neiche-huutschn-diismoi-blond-und-hoib-so-oid', 'Da Huutschnschleidara hod scho wiida a neiche Huutschn - diismoi blond und hoib so oid!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der Hutschenschleuderer hat schon wieder eine neue Hutschen – diesmal blond und halb so alt!', '[{"kategorie": "wörtlich", "text": "\"Dieser Schürzenjäger hat schon wieder ein neues Hutschpferd – diesmal blond und halb so alt!\"  2. Der alte Aufreißer hat sich schon wieder ein neues Reitgerät angelacht – diesmal blond und frisch von der Uni!  3. Der Typ sammelt Hutschpferde wie Trophäen – die aktuelle Ausgabe ist blond, knackig und frisch von der Uni!"}]'::jsonb, ''),
  ('dea-typ-is-nix-oisa-huutschnschleidara-niagands-laenger-ois-a-poa-toog-owa-iwaroi-de-goschn-offn-wiara-scheinentiarl', 'Dea Typ is nix oisa Huutschnschleidara - niagands länger ois a poa Toog, owa iwaroi de Goschn offn wiara Scheinentiarl!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der Typ ist nichts als ein Hutschenschleuderer – nirgends länger als ein paar Tage, aber überall die Goschen offen wie ine Scheunentor!', '[{"kategorie": "wörtlich", "text": "\"Der Typ ist doch nichts als ein  Tagelöhner – nirgendwo länger als nötig , aber überall groß am Reden!\"  2. Der Typ ist doch nichts als ein Rumhänger – kurz da, macht Lärm, und dann ist er auch schon wieder weg!  3. Der Kerl ist ein Taugenichts mit viel mehr Schein als Sein – versprüht heiße Luft, ist überall ein bisschen dabei, aber nirgends länger als ein paar Tage!"}]'::jsonb, ''),
  ('da-huutschschleidara-hod-sei-eigane-technik-ea-katapultiad-de-kinda-mit-an-kraeftign-doppaeschuub-und-an-braadn-grinsn-ind-luft', 'Da Huutschschleidara hod sei eigane Technik - ea katapultiad de Kinda mit an kräftign Doppäschuub und an braadn Grinsn ind Luft!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Der Hutschenschleuderer hat seine eigene Technik – er katapultiert die Kinder mit einem kräftigen Doppelschub und einem breiten Grinsen in die Luft!', '[{"kategorie": "wörtlich", "text": "\"Der Schaukelanschieber hat seine eigene Technik – er katapultiert die Kinder mit einem kräftigen Doppelschub und einem breiten Grinsen in die Luft!\"  2. Der Schaukeldrücker hat seinen eigenen Stil – mit Schwung, Timing und einem Lächeln bringt er jedes Kind zum Fliegen!  3. Der Hutschenschleuderer ist wie ein Zauberer – zwei Schübe, ein Lachen – und schon fliegt das Kind wie ein Vogel im Wind!"}]'::jsonb, ''),
  ('da-huutschnschleidara-vom-prooda-dea-schwimmt-im-goeoed-waeu-des-is-da-ringlschbueuekeenich-und-schaeaef-aum-plotz', 'Da Huutschnschleidara vom Prooda? Dea schwimmt im Gööd, wäu des is da Ringlschbüükeenich und Schääf aum Plotz!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der Hutschenschleuderer vom Prater? Der schwimmt im Geld, denn das ist der Ringelspielkönig und Chef am Platz!', '[{"kategorie": "wörtlich", "text": "\"Der Schaustellerkaiser vom Prater? Der schwimmt im Geld, denn das ist der Karussellkönig und Chef am Platz!\"  2. Der Hutschenschleuderer ist der Patriarch im Prater – ein Karussellönig, der das große Geld dreht!  3. Vom Schausteller zum Millionär und Chef am Platz – der Praterkönig lebt’s vor!"}]'::jsonb, ''),
  ('huutsch-di', 'Huutsch di!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Hutsch dich!', '[{"kategorie": "wörtlich", "text": "\"Schwing dich davon!\"  2. Hau ab!  3. Verschwinde!  4. [[Schleich]] di!  5. [[Vazupf]] di!  6. [[Putz]] di!  7. [[Gee]] in Oasch!  8. [[Hau]] di in Rettich!  9. [[Moch]] Määta!  10. [[Gee]] päule!  11. [[Moch]] a Woikn!"}]'::jsonb, ''),
  ('ea-soogd-zu-ia-mei-huutschpfead-und-si-zu-eam-mei-rummaeplotz-romeo-des-soogd-woi-gmua-aus-iwa-de-zwaa', 'Ea soogd zu ia ''Mei Huutschpfead'' und si zu eam ''Mei Rummäplotz-Romeo'' - des soogd woi gmua aus iwa de zwaa!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Er sagt zu ihr ''mein Hutschpferd'' und sie zu ihm ''mein Rummelplatz-Romeo'' - das sagt wohl genug aus über die zwei!', '[{"kategorie": "wörtlich", "text": "\"Er nennt sie ''mein Hutschpferd'' und sie ihn ''mein Karussell-Casanova'' – das sagt wohl genug aus über die beiden!\"  2. Wenn er zu ihr ‚mein Hutschpferd‘ sagt und sie zu ihm ‚mein Rummelhengst‘, dann ist sofort klar, dass sich die beiden im Prater kennengelernt haben!  3. Er nennt sie ''mein Hutschpferd'' und sie ihn ''mein Karussell-Casanova''  - und ich sag dir: ''Dauerreiterin'' und à''Hutschenschleuderer'' würde noch besser passen!"}]'::jsonb, ''),
  ('grinsn-wiara-huutschpfead', 'grinsn wiara Huutschpfead', '', '', '', 'Wiener Sprüche, die sitzen!', 'grinsen wie ein Hutschpferd', '[{"kategorie": "wörtlich", "text": "\"grinsen wie ein Honigkuchenpferd\""}, {"kategorie": "", "text": "\"breit und glückselig grinsen\""}, {"kategorie": "", "text": "\"grinsen bis über beide Ohren\""}, {"kategorie": "", "text": "\"strahlen wie ein Weihnachtsbaum\""}]'::jsonb, 'Kaum siichta a Blondiine, grinsta wiara Huutschpfead beim Schduutnrennan!'),
